package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	// Build base query
	query := fmt.Sprintf("SELECT id, name, price, description FROM products WHERE category = '%s'", category)

	// Add price filter if provided
	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	// Add sorting - validated against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if sortField != "" && allowedSorts[sortField] {
		query += fmt.Sprintf(" ORDER BY %s", sortField)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		// Manual JSON construction to avoid reflection overhead
		jsonLine := fmt.Sprintf(`  {"id": %d, "name": "%s", "price": %.2f, "description": "%s"}`,
			id, strings.ReplaceAll(name, `"`, `\"`), price, strings.ReplaceAll(description, `"`, `\"`))
		w.Write([]byte(jsonLine))
		first = false
	}
	w.Write([]byte("\n]"))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
